diff --git a/mailnews/compose/src/OutgoingServerService.sys.mjs b/mailnews/compose/src/OutgoingServerService.sys.mjs
index 46651c290ad..01e8382c7aa 100644
--- a/mailnews/compose/src/OutgoingServerService.sys.mjs
+++ b/mailnews/compose/src/OutgoingServerService.sys.mjs
@@ -46,7 +46,11 @@ export class OutgoingServerService {
   }

   set defaultServer(server) {
-    Services.prefs.setCharPref("mail.smtp.defaultserver", server.key);
+    if (server) {
+      Services.prefs.setCharPref("mail.smtp.defaultserver", server.key);
+    } else {
+      Services.prefs.clearUserPref("mail.smtp.defaultserver");
+    }
   }

   get servers() {
